Dans la section Code de la fonction, collez le code dans le fichier lambda_function.py.import zipfile import urllib.parse from io import BytesIO from mimetypes import guess_type import boto3 import logging
s3 = boto3.client('s3') logging.getLogger().setLevel(logging.INFO)
# Target path to unzip the archive. TARGET_PATH = "target"
def lambda_handler(event, context): # Bucket's name. bucket = event['Records'][0]['s3']['bucket']['name'] logging.info("Using bucket: " + bucket);
# Zip file's name. zip_key = urllib.parse.unquote_plus(event['Records'][0]['s3']['object']['key']) logging.info("File to unzip: " + zip_key); logging.info("Path to unzp the files: " + TARGET_PATH);
try: # Get the zipfile from S3 request. obj = s3.get_object(Bucket=bucket, Key=zip_key) z = zipfile.ZipFile(BytesIO(obj['Body'].read()))
# Extract and upload each file to the bucket. for filename in z.namelist(): content_type = str(guess_type(filename, strict=False)[0]) s3.upload_fileobj( Fileobj=z.open(filename), Bucket=bucket, Key=TARGET_PATH + filename, ExtraArgs={'ContentType': content_type} )
# Delete the archive after extraction. s3.delete_object(Bucket=bucket, Key=zip_key) except Exception as error: print(f"An error occurred {error=}")Si vous souhaitez indiquer un chemin cible personnalisé, modifiez la variable TARGET_PATH. Par exemple, pour décompresser l'archive dans le dossier Documentation, définissez la variable comme suit : TARGET_PATH = "Documentation/.
